package com.lbos.commercecustomer.controller; import com.lbos.commercecustomer.dto.request.*;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.time.OffsetDateTime;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/customers") public class CustomerController {private final CustomerService service;public CustomerController(CustomerService s){service=s;}private <T> ApiResponse<T> ok(HttpServletRequest r,String m,T d){return ApiResponse.of(Optional.ofNullable(r.getHeader("X-Correlation-Id")).orElse("not-provided"),m,d);}@PostMapping public ResponseEntity<ApiResponse<CustomerResponse>> create(@Valid @RequestBody CreateCustomerRequest r,HttpServletRequest h){return ResponseEntity.status(201).body(ok(h,"Customer created",service.create(r)));}@GetMapping("/me") public ApiResponse<CustomerResponse> me(HttpServletRequest h){return ok(h,"Customer retrieved",service.me());}@GetMapping public ApiResponse<PageResponse<CustomerResponse>> search(@RequestParam(required=false) String status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,HttpServletRequest h){return ok(h,"Customers retrieved",service.search(status,page,size));}@PatchMapping("/me") public ApiResponse<CustomerResponse> update(@Valid @RequestBody UpdateCustomerRequest r,HttpServletRequest h){return ok(h,"Customer updated",service.update(r));}@DeleteMapping("/me") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(){service.deleteMe();}}